#!/usr/bin/env python3
"""Build a local review index from actual iOS captures and their route metadata."""
import json,html
from pathlib import Path
root=Path('store/pearl-redesign/gallery');items=[]
for p in sorted(root.glob('*.json')):
 data=json.loads(p.read_text());png=p.with_suffix('.png')
 if png.exists():items.append((p,png,data))
figures=[]
for meta,png,d in items:
 title=f"{d['route']} · {d['logicalWidth']:g} × {d['logicalHeight']:g} · text {d['textScale']:g}"
 kind='study' if d['route'][0:2] in ['A-','B-','C-'] else d['route'].split(':')[0]
 video=png.with_suffix('.mp4')
 media=f'<video controls preload="none" poster="{png.name}"><source src="{video.name}" type="video/mp4"></video>' if video.exists() else f'<a href="{png.name}"><img loading="lazy" src="{png.name}" alt="{html.escape(title)}"></a>'
 figures.append(f'<figure data-family="{html.escape(kind)}" data-label="{html.escape(title.lower())}">{media}<figcaption><b>{html.escape(title)}</b><br>{d["pixelWidth"]:g} × {d["pixelHeight"]:g} px · {d["devicePixelRatio"]:g}× · {"motion reduced" if d["reduceMotion"] else "motion on"}<br><a href="{meta.name}">Route, fixture, build & checks</a>{"<br><strong>Needs revision: render errors recorded</strong>" if d.get("errors") else ""}</figcaption></figure>')
(root/'index.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>HolyHim · Pearl light review</title><style>*{box-sizing:border-box}body{font:16px/1.5 system-ui;background:#fff9fb;color:#382331;margin:0;padding:32px}header{max-width:850px;margin:0 auto 32px}h1{font-size:32px;font-weight:600}p{color:#735867}a{color:#9c456b}input,select{font:inherit;border:1px solid #735867;border-radius:12px;padding:12px;background:white;margin:4px}main{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:28px}figure{margin:0;background:white;border:1px solid #e9d4df;border-radius:24px;padding:12px}img{width:100%;height:580px;object-fit:contain;object-position:top}figcaption{padding:16px 8px;font-size:14px}strong{color:#9c263b}.comparison{width:100%;height:auto;max-width:1050px;display:block;margin:20px auto}video{width:100%;max-height:640px}</style><header><h1>HolyHim · Morning light through pearl glass</h1><p>Local redesign review. These are native iOS simulator captures of real routes with isolated fixtures. Each capture records logical and pixel geometry, text scale, fixture, native font resolution and application code hash. Simulator evidence does not establish physical-device feel or performance.</p><p><a href="../REVIEW.md">Critique and revisions</a> · <a href="../VERIFICATION.md">Verification and remaining gates</a> · <a href="native-rounded-specimen.png">Native UIKit font specimen</a></p><input id="q" type="search" placeholder="Find a route, size or state" aria-label="Filter captures"><select id="family" aria-label="Screen family"><option value="">All families</option>'''+''.join(f'<option>{x}</option>' for x in sorted({d['route'].split(':')[0] if d['route'][0:2] not in ['A-','B-','C-'] else 'study' for _,_,d in items}))+'''</select></header><details><summary>Rendered Cognein references at the pinned commit</summary><p>Actual welcome; original name-stage scaffold; original lesson surface with comparison copy. Full authenticated reference journeys and motion parity were not captured.</p><div style="display:flex;gap:20px;flex-wrap:wrap"><img style="width:30%;min-width:240px" src="../reference/cognein-welcome-393.png" alt="Cognein actual welcome"><img style="width:30%;min-width:240px" src="../reference/cognein-name-393.png" alt="Cognein original name stage"><img style="width:30%;min-width:240px" src="../reference/cognein-surface-393.png" alt="Cognein original lesson surface specimen"></div></details><details><summary>Compare the three material studies</summary><img class="comparison" src="comparison-nine.png" alt="Nine comparison frames: Pearl light, Ribbon and paper, Porcelain sanctuary"></details><main>'''+''.join(figures)+'''</main><script>function filter(){let q=document.querySelector('#q').value.toLowerCase(),f=document.querySelector('#family').value;document.querySelectorAll('figure').forEach(e=>e.hidden=!(e.dataset.label.includes(q)&&(!f||e.dataset.family===f)))}document.querySelector('#q').oninput=filter;document.querySelector('#family').onchange=filter</script></html>''')
print('Indexed',len(items),'native captures')
